// TH16 v1.00a Stage 5 boss parallel non-spell 1.
// Source: st05bs.ecl.txt Boss1 (70-98) / Boss1B (100-127); both entries run in
// parallel and share one 2400-frame interrupt window:
//   setInterrupt(0, 2000, 2400, "BossCard1"/"BossCard1B")
// Dependencies: Boss1_at (247-291), Boss1_at1B (293-337),
//               Boss1B_at (129-171), Boss1B_at1B (173-215).
// Entry position from context: Boss -> movePosTime(60,4,64,128) before @Boss1();
// BossB -> movePos(-64,128) before @Boss1B().

const TH16_TALISMAN: int = 528;

const TIME_LIMIT: int = 2524;      // 120 shell buffer + 2400 source window + 4 start margin
const OPENING_BUFFER: int = 120;
const INTRO_WAIT: int = 60;        // source wait(60) between anmPlay(1,75) and anmPlay(1,86)
const RING_GAP: int = 20;          // source wait(20) between ring volleys

// ---------------------------------------------------------------------------
// Boss1_at / Boss1_at1B fire tails.
// Source: ANIM a=1 (position -= 4*velocity at birth) then four STEP records
// with a=60/60/50/40, b=1, c=0, d=0, s=-999999 (keep speed).
// STEP ramps the drawn speed linearly down to 0 across each segment and
// restores the target speed at the segment boundary (ex-effects.md "STEP").
// Segment turns: Boss1_at +30,-60,+90,-120 deg; Boss1_at1B mirrored.
// Each "@a step_speed(0fx,a)" launches the deceleration and resumes the
// cursor on the tick the STEP writes its exact 0; turn/set_speed then land on
// that same tick, matching the native segment boundary.
// ---------------------------------------------------------------------------
xformdef BOSS1_STEP_A(v: fx) {
    @60 step_speed(0fx, 60);
    turn(30deg);
    set_speed(v);
    @60 step_speed(0fx, 60);
    turn(-60deg);
    set_speed(v);
    @50 step_speed(0fx, 50);
    turn(90deg);
    set_speed(v);
    @40 step_speed(0fx, 40);
    turn(-120deg);
    set_speed(v);
}

xformdef BOSS1_STEP_B(v: fx) {
    @60 step_speed(0fx, 60);
    turn(-30deg);
    set_speed(v);
    @60 step_speed(0fx, 60);
    turn(60deg);
    set_speed(v);
    @50 step_speed(0fx, 50);
    turn(-90deg);
    set_speed(v);
    @40 step_speed(0fx, 40);
    turn(120deg);
    set_speed(v);
}

// Boss1B_at / Boss1B_at1B: ANIM a=1, OFFSCREEN a=240 (b=0), then
// ANGLE_ACCEL a=600, r=0.012 speed/frame, s=+/-0.011635528 rad/frame
// (= 121.36 BAM/frame). OFFSCREEN does not stall the EX cursor with async=0,
// so the spin runs concurrently with the keep-alive countdown.
xformdef BOSS1B_SPIN(omega: angle) {
    offscreen_keep(240);
    set_ang_vel(omega);
    set_accel(0.012fx);
    wait(600);
    set_accel(0fx);
    set_ang_vel(0deg);
}

// ---------------------------------------------------------------------------
// moveRand(60,4,1.0) helper (movement.md recipe).
// Speed ramps 1 -> 0 over 60 steps; the limit clamp is applied every tick.
// self_int(0) = next source movement tick count, self_fx(0/1) = unit direction.
// ---------------------------------------------------------------------------
sub mr_arm(xmin: fx, xmax: fx) {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var s: fx = 0fx;
    if k < 60 { s = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * s;
    var ny: fx = $self_y + self_fx(1) * s;
    if nx < xmin { nx = xmin; }
    if nx > xmax { nx = xmax; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub mr_begin(a: angle, xmin: fx, xmax: fx) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    mr_arm(xmin, xmax);
}

sub mr_wait(n: int, xmin: fx, xmax: fx) {
    for i in 0..n {
        wait(1);
        mr_arm(xmin, xmax);
    }
}

// Source 412 direction pick. Branch inner zone is the moveLimit rectangle's
// inner quarter (center +/- width/4, center +/- height/4); the position clamp
// is the full rectangle (center +/- width/2, center +/- height/2).
sub mr_start(cx: fx, cy: fx, hw: fx, hh: fx) {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    var iw: fx = hw / 2fx;
    var ih: fx = hh / 2fx;
    var choose: int = 0;
    if $self_x < cx - iw {
        a = r / 3;
    } else if $self_x > cx + iw {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        choose = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < cy - ih {
        if a < 0 { a = -a; }
    } else if $self_y > cy + ih {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    mr_begin(a as angle, cx - hw, cx + hw);
}

// One ring sweep: source do-while A starts at pi/2 and shifts by 2 deg per
// volley, one etOn ring every wait(20).
sub ring_sweep(n: int, base: angle, da: angle) {
    var a: angle = base;
    var i: int = 0;
    while i < n {
        sh_angle(0, a, 0deg);
        sh_fire(0);
        wait(RING_GAP);
        a = a + da;
        i = i + 1;
    }
}

// ---------------------------------------------------------------------------
// Real enemies
// ---------------------------------------------------------------------------
async sub main_boss() {
    set_invuln(65535);
    set_hurtbox(20fx);              // source setHurtbox(40,40), circular r = 40*0.5
    set_hitbox(24fx);               // source setHitbox(48,48), circular r = 48*0.5

    var rank: int = global(GVAR_RANK);
    var ways: int = 12;             // !E 12 / !N 16 / !H 24 / !LO 24
    if rank >= RANK_HARD { ways = 24; } else if rank >= RANK_NORMAL { ways = 16; }
    var speed: fx = 2fx;            // !E 2.0 / !N 2.0 / !H 2.5 / !LO 3.0
    if rank >= RANK_LUNATIC { speed = 3fx; } else if rank >= RANK_HARD { speed = 2.5fx; }

    sh_reset(0);
    sh_sprite(0, TH16_TALISMAN, 4); // etSprite(0,11,4)
    sh_aim(0, 0);                   // etAim(0,3): fixed-direction ring
    sh_ring(0, 1);
    sh_count(0, ways, 1);           // etCount(0,[-1],1)
    sh_speed(0, speed, 0fx);        // etSpeed(0,[-1.0f],1.2f); one layer -> speed0
    // etDist(0,20.0f) forward along each bullet's angle, composed with the
    // ANIM a=1 birth displacement position -= 4*velocity -> net 20 - 4*speed.
    sh_dist(0, 20fx - 4fx * speed);

    wait(INTRO_WAIT);

    loop {
        sh_xform(0, BOSS1_STEP_A(speed));
        ring_sweep(10, 90deg, -2deg);          // Boss1_at
        wait(20);
        mr_start(96fx, 128fx, 72fx, 32fx);     // moveRand(60,4,1.0), moveLimit(96,128,144,64)
        mr_wait(70, 24fx, 168fx);
        sh_xform(0, BOSS1_STEP_B(speed));
        ring_sweep(10, 90deg, 2deg);           // Boss1_at1B
        wait(20);
        mr_start(96fx, 128fx, 72fx, 32fx);
        mr_wait(70, 24fx, 168fx);
    }
}

async sub b_boss() {
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);

    var rank: int = global(GVAR_RANK);
    var ways: int = 12;             // same difficulty counts as Boss1B_at
    if rank >= RANK_HARD { ways = 24; } else if rank >= RANK_NORMAL { ways = 16; }
    var speed: fx = 2fx;            // !E 2.0 / !N 2.0 / !H 3.0 / !LO 3.0
    if rank >= RANK_HARD { speed = 3fx; }

    sh_reset(0);
    sh_sprite(0, TH16_TALISMAN, 10); // etSprite(0,11,10)
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, ways, 1);
    sh_speed(0, speed, 0fx);
    sh_dist(0, 20fx - 4fx * speed);  // etDist 20 composed with ANIM -4*velocity

    wait(INTRO_WAIT);

    loop {
        sh_xform(0, BOSS1B_SPIN(121bam));      // Boss1B_at: s=+0.011635528 rad/frame
        ring_sweep(8, 90deg, -2deg);
        wait(20);
        mr_start(-96fx, 128fx, 72fx, 32fx);    // moveLimit(-96,128,144,64)
        mr_wait(70, -168fx, -24fx);
        sh_xform(0, BOSS1B_SPIN(-121bam));     // Boss1B_at1B: s=-0.011635528 rad/frame
        ring_sweep(8, 90deg, 2deg);
        wait(20);
        mr_start(-96fx, 128fx, 72fx, 32fx);
        mr_wait(70, -168fx, -24fx);
    }
}

// ---------------------------------------------------------------------------
// Independent invulnerable shell (validation.md): control owns the segment,
// real enemies keep source hitbox/body collision and move.
// ---------------------------------------------------------------------------
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(64fx, 128fx, 1000, 0, 0, 0, main_boss);
    _ = spawn_enemy(-64fx, 128fx, 1000, 0, 0, 0, b_boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
